const input = $('Webhook').first().json;
const clause = input.body || input;

if (!clause.clause_text) {
  throw new Error('clause_text is required');
}

return [{
  json: {
    clause_instance_id: clause.clause_instance_id || 'unknown',
    clause_id: clause.clause_id || 'unknown',
    clause_text: clause.clause_text,
    heading: clause.heading || '',
    probable_category: clause.probable_category || '',
    run_id: clause.run_id || '',
    document_id: clause.document_id || '',
    // 3-Layer context from W3
    blueprint_version_id: clause.blueprint_version_id || null,
    contract_model_version_id: clause.contract_model_version_id || null,
    started_at: new Date().toISOString()
  }
}];

const inputData = $('Parse Input').first().json;
const embeddingResponse = $('Generate Clause Embedding').first().json;

let clauseEmbedding = null;
try {
  clauseEmbedding = embeddingResponse.data?.[0]?.embedding || null;
} catch (e) {
  console.log('Embedding extraction error:', e.message);
}

return [{
  json: {
    ...inputData,
    clauseEmbedding,
    hasEmbedding: clauseEmbedding !== null
  }
}];

const inputData = $('Extract Embedding').first().json;
const ragResults = $input.all();

// Organizar ejemplos por acceptance level
const examples = {
  ACCEPTABLE: [],
  PASSABLE: [],
  UNACCEPTABLE: [],
  all: []
};

for (const item of ragResults) {
  const ex = item.json;
  if (ex && ex.id) {
    const entry = {
      id: ex.id,
      text: ex.example_text?.substring(0, 500) || '',
      similarity: ex.similarity || 0,
      acceptance: ex.acceptance,
      clause_type: ex.clause_type_name || 'unknown'
    };
    examples.all.push(entry);
    if (ex.acceptance && examples[ex.acceptance]) {
      examples[ex.acceptance].push(entry);
    }
  }
}

// Determinar acceptance sugerido basado en ejemplos más similares
let suggestedAcceptance = 'NEEDS_REVIEW';
let topSimilarity = 0;
if (examples.all.length > 0) {
  const top3 = examples.all.slice(0, 3);
  const acceptableSimilarity = top3.filter(e => e.acceptance === 'ACCEPTABLE').reduce((sum, e) => sum + e.similarity, 0);
  const passableSimilarity = top3.filter(e => e.acceptance === 'PASSABLE').reduce((sum, e) => sum + e.similarity, 0);
  const unacceptableSimilarity = top3.filter(e => e.acceptance === 'UNACCEPTABLE').reduce((sum, e) => sum + e.similarity, 0);

  topSimilarity = examples.all[0].similarity;

  if (acceptableSimilarity > passableSimilarity && acceptableSimilarity > unacceptableSimilarity) {
    suggestedAcceptance = 'ACCEPTABLE';
  } else if (unacceptableSimilarity > acceptableSimilarity && unacceptableSimilarity > passableSimilarity) {
    suggestedAcceptance = 'UNACCEPTABLE';
  } else {
    suggestedAcceptance = 'PASSABLE';
  }
}

console.log(`RAG found ${examples.all.length} examples. Top similarity: ${topSimilarity.toFixed(3)}. Suggested: ${suggestedAcceptance}`);

return [{
  json: {
    ...inputData,
    ragExamples: examples,
    ragStats: {
      totalFound: examples.all.length,
      acceptableCount: examples.ACCEPTABLE.length,
      passableCount: examples.PASSABLE.length,
      unacceptableCount: examples.UNACCEPTABLE.length,
      topSimilarity,
      suggestedAcceptance
    }
  }
}];

const prevData = $('Process RAG Results').first().json;
let routerOutput = { matter_code: 'miscellaneous', confidence: 0, reasoning: '' };

try {
  const response = $json;
  const content = response.choices?.[0]?.message?.content || '{}';
  routerOutput = JSON.parse(content);
} catch (e) {
  console.log('Router parse error:', e.message);
}

return [{ json: { ...prevData, routerOutput } }];

