const prevData = $('Parse Paranoid').first().json;
let valuatorOutput = { 
  acceptance: 'PASSABLE',
  confidence: 0.5,
  reasoning: '',
  proposed_changes: [],
  client_state: 'NEEDS_REVIEW',
  internal_comment: ''
};

try {
  const content = $json.choices?.[0]?.message?.content || '{}';
  valuatorOutput = JSON.parse(content);
} catch (e) {
  console.log('Valuator parse error:', e.message);
}

// Map acceptance to client_state if not provided
if (!valuatorOutput.client_state) {
  const stateMap = {
    'ACCEPTABLE': 'OK',
    'PASSABLE': 'RECOMMENDED',
    'UNACCEPTABLE': 'REQUIRED'
  };
  valuatorOutput.client_state = stateMap[valuatorOutput.acceptance] || 'NEEDS_REVIEW';
}

return [{ json: { ...prevData, valuatorOutput } }];

const data = $('Parse Valuator').first().json;
const valOut = data.valuatorOutput;

// Decisor logic
let decision = 'ESCALATE_HUMAN';
let escalation = { recommended: false, block_export: false, reason: '' };
let client_state = valOut.client_state || 'NEEDS_REVIEW';

const acceptance = valOut.acceptance;
const confidence = valOut.confidence || 0;

if (acceptance === 'ACCEPTABLE' && confidence >= 0.7) {
  decision = 'AUTO_PASS';
  client_state = 'OK';
} else if (acceptance === 'PASSABLE') {
  decision = 'AUTO_PASS';
  client_state = 'RECOMMENDED';
} else if (acceptance === 'UNACCEPTABLE') {
  decision = 'AUTO_REDLINE';
  client_state = 'REQUIRED';
  escalation = { recommended: true, block_export: false, reason: 'UNACCEPTABLE_CLAUSE' };
} else {
  decision = 'ESCALATE_HUMAN';
  client_state = 'NEEDS_REVIEW';
  escalation = { recommended: true, block_export: false, reason: 'LOW_CONFIDENCE' };
}

return [{ json: { 
  ...data, 
  decisorOutput: { decision, escalation, client_state, acceptance } 
}}];

