const data = $('Decisor').first().json;
let sanitizerOut = { client_comment: '', client_summary_line: '' };

try {
  const content = $json.choices?.[0]?.message?.content || '{}';
  sanitizerOut = JSON.parse(content);
} catch (e) {
  sanitizerOut.client_comment = 'Cláusula revisada según estándares del contrato.';
  sanitizerOut.client_summary_line = 'Revisión completada';
}

const result = {
  // IDs
  clause_instance_id: data.clause_instance_id,
  clause_id: data.clause_id,
  document_id: data.document_id,
  run_id: data.run_id,

  // Content
  heading: data.heading || data.routerOutput.matter_code,
  clause_text: data.clause_text,
  detected_family: data.routerOutput.matter_code,
  confidence_score: data.routerOutput.confidence || 0,

  // 3-Layer fields
  blueprint_version_id: data.blueprint_version_id,
  acceptance: data.decisorOutput.acceptance,

  // RAG Evidence
  evidence: {
    rag_examples_used: data.ragExamples.all.slice(0, 5).map(e => e.id),
    top_similarity: data.ragStats.topSimilarity,
    suggested_by_rag: data.ragStats.suggestedAcceptance,
    paranoid_risk: data.paranoidOutput.risk_level,
    valuator_confidence: data.valuatorOutput.confidence
  },

  // Client-facing
  client_state: data.decisorOutput.client_state,
  client_comment: sanitizerOut.client_comment,
  client_summary_line: sanitizerOut.client_summary_line,

  // Changes
  proposed_changes: data.valuatorOutput.proposed_changes || [],

  // Escalation
  escalation_recommended: data.decisorOutput.escalation?.recommended || false,
  escalation_reason: data.decisorOutput.escalation?.reason || null,

  completed_at: new Date().toISOString()
};

return [{ json: result }];
